const uploadItems = $input.all();
const normalizedItems = $('Normalize Image Binary and Metadata').all();
const preparedItems = $('User Input Prepare').all();
const sharedInput = $('sysPrompt').first().json || {};

if (uploadItems.length < 1 || uploadItems.length > 5) {
  throw new Error('Expected 1-5 SiliconFlow upload responses, received ' + uploadItems.length);
}
if (normalizedItems.length !== uploadItems.length || preparedItems.length !== uploadItems.length) {
  throw new Error('Image pipeline count mismatch: prepared=' + preparedItems.length + ', normalized=' + normalizedItems.length + ', uploaded=' + uploadItems.length);
}

const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const preparedByIndex = new Map(
  preparedItems.map((item, position) => [Number(item.json.imageIndex ?? position), item.json]),
);

const uploadedImages = uploadItems.map((item, position) => {
  const response = item.json || {};
  if (response.status === false) {
    throw new Error('SiliconFlow upload ' + (position + 1) + ' failed: ' + (response.message || response.msg || 'unknown error'));
  }
  if (response.code !== undefined && response.code !== null && Number(response.code) !== 20000) {
    throw new Error('SiliconFlow upload ' + (position + 1) + ' failed with code ' + response.code + ': ' + (response.message || response.msg || 'unknown error'));
  }

  const data = response.data && typeof response.data === 'object' ? response.data : {};
  const url = clean(data.object || data.url || response.url);
  if (!url) throw new Error('SiliconFlow upload ' + (position + 1) + ' did not return an image URL');

  const normalized = normalizedItems[position]?.json || {};
  const imageIndex = Number.isFinite(Number(normalized.imageIndex)) ? Number(normalized.imageIndex) : position;
  const prepared = preparedByIndex.get(imageIndex) || preparedItems[position]?.json || {};
  return {
    imageIndex,
    imageSource: clean(prepared.imageSource || normalized.imageSource),
    url,
  };
}).sort((a, b) => a.imageIndex - b.imageIndex);

const shared = sharedInput.constants || {};
const modelRun = clean(shared.model?.Model_Run);
const baseUrlRun = clean(shared.BaseUrl?.BaseUrl_Run);
const apiKeyRun = clean(shared.Authorization?.APIKey_Run);
const systemPrompt = clean(sharedInput.sysPrompt);
if (!modelRun) throw new Error('Missing constants.model.Model_Run');
if (!baseUrlRun) throw new Error('Missing constants.BaseUrl.BaseUrl_Run');
if (!apiKeyRun) throw new Error('Missing constants.Authorization.APIKey_Run');
if (!systemPrompt) throw new Error('Missing system prompt');

const prepared = preparedItems[0]?.json || {};
const content = [
  ...uploadedImages.map((image) => ({
    type: 'image_url',
    image_url: { url: image.url },
  })),
  { type: 'text', text: prepared.userPrompt },
];

for (const [index, item] of content.entries()) {
  if (!item || (item.type !== 'image_url' && item.type !== 'text')) {
    throw new Error('Invalid Qwen content item type at index ' + index);
  }
  if (item.type === 'image_url') {
    const imageUrl = clean(item.image_url?.url);
    if (!/^https?:\/\//i.test(imageUrl)) {
      throw new Error('Invalid Qwen image URL at content index ' + index);
    }
  }
  if (item.type === 'text' && !clean(item.text)) {
    throw new Error('Qwen user text is empty');
  }
}

const request = {
  model: modelRun,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content },
  ],
  enable_thinking: false,
  response_format: { type: 'json_object' },
  temperature: 0.2,
};

return [{
  json: {
    request,
    constants: {
      ...shared,
      model: {
        ...(shared.model || {}),
        Model_Run: modelRun,
      },
      BaseUrl: {
        ...(shared.BaseUrl || {}),
        BaseUrl_Run: baseUrlRun,
      },
      Authorization: {
        ...(shared.Authorization || {}),
        APIKey_Run: apiKeyRun,
      },
    },
    source: {
      ...($('When Executed by Another Workflow').first().json || {}),
      uploadedImages,
      imageCount: uploadedImages.length,
    },
  },
}];

const source = $('When Executed by Another Workflow').first().json || {};
const shared = $('sysPrompt').first().json || {};

const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const positiveNumber = (value, fallback) => {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : fallback;
};
const extractImageSource = (value) => {
  if (typeof value === 'string') return clean(value);
  if (!value || typeof value !== 'object') return '';
  return clean(value.url ?? value.imageUrl ?? value.imageSource ?? value.path);
};

const numberedKeys = [
  'viewImageAdd1',
  'viewImageAdd2',
  'viewImageAdd3',
  'viewImageAdd4',
  'viewImageAdd5',
];

const numberedImages = numberedKeys
  .map((key) => extractImageSource(source[key] ?? shared[key]))
  .filter(Boolean);

const arrayKeys = ['viewImageAdds', 'imageUrls', 'images', 'viewImages'];
let arrayImages = [];
let arrayInputField = '';

if (numberedImages.length === 0) {
  for (const key of arrayKeys) {
    const candidate = source[key] ?? shared[key];
    let values = [];
    if (Array.isArray(candidate)) {
      values = candidate;
    } else if (candidate && typeof candidate === 'object' && Array.isArray(candidate.items)) {
      values = candidate.items;
    } else if (typeof candidate === 'string' && candidate.trim()) {
      try {
        const parsed = JSON.parse(candidate);
        values = Array.isArray(parsed) ? parsed : [];
      } catch {
        values = [];
      }
    }
    const extracted = values.map(extractImageSource).filter(Boolean);
    if (extracted.length > 0) {
      arrayImages = extracted;
      arrayInputField = key;
      break;
    }
  }
}

const selectedImages = numberedImages.length > 0 ? numberedImages : arrayImages;
if (selectedImages.length < 1 || selectedImages.length > 5) {
  throw new Error('Expected 1-5 image inputs, received ' + selectedImages.length);
}

const imageSources = selectedImages.map((value) => value.replace(/\\/g, '/'));
const userInput = {
  Category: clean(source.Category ?? shared.Category),
  productName: clean(source.productName ?? shared.productName),
  productDescription: clean(source.productDescription ?? shared.productDescription),
  targetPlatform: clean(source.targetPlatform ?? shared.targetPlatform),
  Country: clean(source.Country ?? shared.Country),
  Language: clean(source.Language ?? shared.Language),
  titleLength: positiveNumber(source.titleLength ?? shared.titleLength, 20),
  titleDescriptionLenth: positiveNumber(source.titleDescriptionLenth ?? shared.titleDescriptionLenth, 60),
  ratio: clean(source.ratio ?? shared.ratio),
  imageCount: imageSources.length,
};

const userInputJson = JSON.stringify(userInput, null, 2);
const userPrompt = [
  '下面是当前电商主图场景编排任务。',
  '请严格遵循系统提示词，结合用户输入 JSON、类目规则，以及后续上传的全部产品参考图完成输出。',
  '本次实际提供 ' + imageSources.length + ' 张产品参考图，请综合识别，不要遗漏。',
  '用户输入 JSON：',
  userInputJson,
].join('\n');

return imageSources.map((imageSource, imageIndex) => ({
  json: {
    imageIndex,
    imageSource,
    isUrl: /^https?:\/\//i.test(imageSource),
    imageCount: imageSources.length,
    imageInputMode: numberedImages.length > 0 ? 'numbered' : arrayInputField,
    userInputJson,
    userPrompt,
  },
  pairedItem: { item: 0 },
}));

const response = $input.first().json || {};
let content = response?.choices?.[0]?.message?.content ?? response?.message?.content ?? response?.content;
const productName = String($('When Executed by Another Workflow').first().json.productName ?? '');

if (content && typeof content === 'object') {
  return [{ json: { ...content, productName } }];
}

if (typeof content !== 'string') {
  throw new Error('Qwen response did not include choices[0].message.content.');
}

let text = content.trim();
const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
if (fenced) {
  text = fenced[1].trim();
}

function parseJson(raw) {
  try {
    return JSON.parse(raw);
  } catch (error) {
    const firstBrace = raw.indexOf('{');
    const lastBrace = raw.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace > firstBrace) {
      return JSON.parse(raw.slice(firstBrace, lastBrace + 1));
    }
    throw error;
  }
}

let parsed;
try {
  parsed = parseJson(text);
} catch (error) {
  throw new Error(`Qwen output is not valid JSON: ${error.message}. Output preview: ${text.slice(0, 500)}`);
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('Qwen output JSON must be an object.');
}

return [{ json: { ...parsed, productName } }];

const items = $input.all();
const preparedItems = $('User Input Prepare').all();

return items.map((item, position) => {
  const binary = item.binary || {};
  const indexedKey = Object.keys(binary).find((key) => /^image_\d+$/.test(key));
  if (!indexedKey) throw new Error('Image binary ' + (position + 1) + ' is missing its indexed property');

  const imageIndex = Number(indexedKey.slice('image_'.length));
  const prepared = preparedItems.find((candidate) => Number(candidate.json.imageIndex) === imageIndex)?.json;
  if (!prepared) throw new Error('No prepared image metadata found for imageIndex ' + imageIndex);

  return {
    json: {
      imageIndex,
      imageSource: prepared.imageSource,
      imageCount: prepared.imageCount,
    },
    binary: { data: binary[indexedKey] },
    pairedItem: { item: position },
  };
});
